package com.saasquatch.intelligence.controller; import com.saasquatch.intelligence.dto.*; import com.saasquatch.intelligence.entity.*; import com.saasquatch.intelligence.repository.*; import com.saasquatch.intelligence.service.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/leads") @CrossOrigin(origins="*") public class LeadController { private final LeadRepository leads; private final ScoringService scoring; private final CorporateRelationshipService relationships; public LeadController(LeadRepository l,ScoringService s,CorporateRelationshipService r){leads=l;scoring=s;relationships=r;} @GetMapping public List<LeadIntelligenceResponse> list(@RequestParam(required=false) String search,@RequestParam(defaultValue="0") int minScore,@RequestParam(required=false) String signal){return leads.findAll().stream().filter(l->search==null||l.getCompany().getName().toLowerCase().contains(search.toLowerCase())||(l.getContactName()!=null&&l.getContactName().toLowerCase().contains(search.toLowerCase()))).map(l->scoring.intelligence(l,relationships.forCompany(l.getCompany().getId()))).filter(x->x.opportunityScore()>=minScore).filter(x->signal==null||x.signals().stream().anyMatch(s->s.type().equalsIgnoreCase(signal))).sorted(Comparator.comparingInt(LeadIntelligenceResponse::opportunityScore).reversed()).toList();} @GetMapping("/{id}/intelligence") public ResponseEntity<LeadIntelligenceResponse> intelligence(@PathVariable Long id){return leads.findById(id).map(l->ResponseEntity.ok(scoring.intelligence(l,relationships.forCompany(l.getCompany().getId())))).orElseGet(()->ResponseEntity.notFound().build());} @GetMapping("/{id}") public ResponseEntity<Lead> detail(@PathVariable Long id){return leads.findById(id).map(ResponseEntity::ok).orElseGet(()->ResponseEntity.notFound().build());} @GetMapping("/{id}/relationships") public List<CorporateRelationship> rels(@PathVariable Long id){return leads.findById(id).map(l->relationships.forCompany(l.getCompany().getId())).orElse(List.of());} }